// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait AvailabilityArbitration_coordination_availability_arbitration_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration)
  }

  /** helper function to set the values of all input ports.
   * @param recoveryFrame payload for data port recoveryFrame
   * @param admissionFrame payload for data port admissionFrame
   * @param artifactFrame payload for data port artifactFrame
   * @param presentationFrame payload for data port presentationFrame
   * @param evidenceFrame payload for data port evidenceFrame
   * @param availabilityFrame payload for data port availabilityFrame
   * @param reviewFrame payload for data port reviewFrame
   */
  def put_concrete_inputs(recoveryFrame : EIT_Image_Availability_Coordinator.RecoveryFrame,
                          admissionFrame : EIT_Image_Availability_Coordinator.AdmissionFrame,
                          artifactFrame : EIT_Image_Availability_Coordinator.ArtifactFrame,
                          presentationFrame : EIT_Image_Availability_Coordinator.PresentationFrame,
                          evidenceFrame : EIT_Image_Availability_Coordinator.EvidenceFrame,
                          availabilityFrame : EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame,
                          reviewFrame : EIT_Image_Availability_Coordinator.ReviewFrame): Unit = {
    put_recoveryFrame(recoveryFrame)
    put_admissionFrame(admissionFrame)
    put_artifactFrame(artifactFrame)
    put_presentationFrame(presentationFrame)
    put_evidenceFrame(evidenceFrame)
    put_availabilityFrame(availabilityFrame)
    put_reviewFrame(reviewFrame)
  }


  /** helper function to check AvailabilityArbitration_coordination_availability_arbitration's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param decisionFrame method that will be called with the value of the outgoing data
   *        port 'decisionFrame'.
   */
  def check_concrete_output(decisionFrame: EIT_Image_Availability_Coordinator.DecisionFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val decisionFrameValue: EIT_Image_Availability_Coordinator.DecisionFrame = get_decisionFrame().get
    if(!decisionFrame(decisionFrameValue)) {
      testFailures = testFailures :+ st"'decisionFrame' did not match expected: value of the outgoing data port is ${decisionFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recoveryFrame(value : EIT_Image_Availability_Coordinator.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.recoveryFrame_Id, EIT_Image_Availability_Coordinator.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_admissionFrame(value : EIT_Image_Availability_Coordinator.AdmissionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.admissionFrame_Id, EIT_Image_Availability_Coordinator.AdmissionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_artifactFrame(value : EIT_Image_Availability_Coordinator.ArtifactFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.artifactFrame_Id, EIT_Image_Availability_Coordinator.ArtifactFrame_Payload(value))
  }

  // setter for in DataPort
  def put_presentationFrame(value : EIT_Image_Availability_Coordinator.PresentationFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.presentationFrame_Id, EIT_Image_Availability_Coordinator.PresentationFrame_Payload(value))
  }

  // setter for in DataPort
  def put_evidenceFrame(value : EIT_Image_Availability_Coordinator.EvidenceFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.evidenceFrame_Id, EIT_Image_Availability_Coordinator.EvidenceFrame_Payload(value))
  }

  // setter for in DataPort
  def put_availabilityFrame(value : EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.availabilityFrame_Id, EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_reviewFrame(value : EIT_Image_Availability_Coordinator.ReviewFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.operational_api.reviewFrame_Id, EIT_Image_Availability_Coordinator.ReviewFrame_Payload(value))
  }

  // getter for out DataPort
  def get_decisionFrame(): Option[EIT_Image_Availability_Coordinator.DecisionFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.DecisionFrame] = get_decisionFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.DecisionFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port decisionFrame.  Expecting 'EIT_Image_Availability_Coordinator.DecisionFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.DecisionFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_decisionFrame_payload(): Option[EIT_Image_Availability_Coordinator.DecisionFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_availability_arbitration.initialization_api.decisionFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.DecisionFrame_Payload]]
  }

}
